{
  "title": "Tính thể tích khối chóp, diện tích thiết diện và khoảng cách từ điểm đến đường thẳng",
  "description": "Bài toán này minh họa cách dựng hình chóp, mặt phẳng cắt, thiết diện và tính toán các đại lượng hình học cơ bản trong không gian Oxyz.",
  "memory_declarations": [
    {
      "name": "S.ABCD",
      "type": "solid",
      "source_fact_id": "s_abcd_pyramid"
    },
    {
      "name": "T",
      "type": "section",
      "source_fact_id": "T_section_def"
    },
    {
      "name": "the_volume_sabcd",
      "type": "float",
      "initial_value": null,
      "source_fact_id": "volume"
    },
    {
      "name": "area_T",
      "type": "float",
      "initial_value": null,
      "source_fact_id": "area"
    },
    {
      "name": "BD",
      "type": "line3",
      "initial_value": null,
      "source_fact_id": "distance"
    },
    {
      "name": "dist_S_BD",
      "type": "float",
      "initial_value": null,
      "source_fact_id": "distance"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "A",
      "at": [0, 0, 0],
      "source_fact_id": "A_coords",
      "model_assumption": "Gốc tọa độ được đặt tại A theo đề bài."
    },
    {
      "kind": "declare_point",
      "target_var": "B",
      "at": [6, 0, 0],
      "source_fact_id": "B_coords"
    },
    {
      "kind": "declare_point",
      "target_var": "C",
      "at": [6, 6, 0],
      "source_fact_id": "C_coords"
    },
    {
      "kind": "declare_point",
      "target_var": "D",
      "at": [0, 6, 0],
      "source_fact_id": "D_coords"
    },
    {
      "kind": "declare_point",
      "target_var": "S",
      "at": [0, 0, 6],
      "source_fact_id": "S_coords"
    },
    {
      "kind": "construct_polygon",
      "target_var": "ABCD_base",
      "vertices": ["A", "B", "C", "D"],
      "label": "Đáy hình vuông ABCD"
    },
    {
      "kind": "construct_solid",
      "target_var": "S.ABCD",
      "vertices": ["S", "A", "B", "C", "D"],
      "faces": [
        ["A", "B", "C", "D"],
        ["S", "A", "B"],
        ["S", "B", "C"],
        ["S", "C", "D"],
        ["S", "D", "A"]
      ],
      "label": "Khối chóp S.ABCD"
    },
    {
      "kind": "construct_plane_from_equation",
      "target_var": "alpha_plane",
      "a": 0,
      "b": 0,
      "c": 1,
      "d": -3,
      "source_fact_id": "alpha_plane_def",
      "label": "Mặt phẳng (α): z = 3"
    },
    {
      "kind": "construct_section",
      "target_var": "T",
      "solid": "S.ABCD",
      "plane": "alpha_plane",
      "label": "Thiết diện (T)"
    },
    {
      "kind": "assign",
      "target_var": "the_volume_sabcd",
      "expr": {
        "kind": "measure",
        "quantity": "volume",
        "of": "S.ABCD"
      }
    },
    {
      "kind": "assign",
      "target_var": "area_T",
      "expr": {
        "kind": "measure",
        "quantity": "area",
        "of": "T"
      }
    },
    {
      "kind": "construct_line",
      "target_var": "BD",
      "through_a": "B",
      "through_b": "D",
      "label": "Đường thẳng BD"
    },
    {
      "kind": "assign",
      "target_var": "dist_S_BD",
      "expr": {
        "kind": "measure",
        "quantity": "distance",
        "of": "S",
        "wrt": "BD"
      }
    }
  ],
  "pedagogical_intent": "Chương trình này giúp học sinh hình dung cách một mặt phẳng cắt một khối chóp tạo ra thiết diện, và cách tính các đại lượng hình học liên quan."
}
